        if (i < n && s[i] != "#") { cur->left = new TreeNode(stoi(s[i])); q.push(cur->left); } ++i;
        if (i < n && s[i] != "#") { cur->right = new TreeNode(stoi(s[i])); q.push(cur->right); } ++i;
    }
    return root;
}

TreeNode* findNode(TreeNode* r, int v) {
    if (!r) return nullptr;
    if (r->val == v) return r;
    TreeNode* l = findNode(r->left, v);
    return l ? l : findNode(r->right, v);
}

